// Dữ liệu phòng ban mẫu
const fakeDepartments = [
  { id: 1, name: 'Kỹ thuật', manager: 'Nguyễn Văn An', count: 8, description: 'Phụ trách phát triển phần mềm và hạ tầng kỹ thuật.' },
  { id: 2, name: 'Marketing', manager: 'Trần Thị Bình', count: 5, description: 'Chịu trách nhiệm truyền thông và quảng bá thương hiệu.' },
  { id: 3, name: 'Kế toán', manager: 'Lê Văn Cường', count: 4, description: 'Quản lý tài chính và báo cáo kế toán.' },
  { id: 4, name: 'Nhân sự', manager: 'Phạm Thị Dung', count: 3, description: 'Tuyển dụng, đào tạo và quản lý nhân viên.' },
  { id: 5, name: 'Hành chính', manager: 'Hoàng Văn Em', count: 4, description: 'Hỗ trợ hành chính và quản lý văn phòng.' },
];

function Departments() {
  return (
    <div>
      <h4 style={{ marginBottom: '4px', color: '#111' }}>Phòng ban</h4>
      <p style={{ color: '#888', fontSize: '14px', marginBottom: '20px' }}>
        Danh sách các phòng ban trong công ty.
      </p>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
        {fakeDepartments.map((dept) => (
          <div
            key={dept.id}
            style={{
              backgroundColor: '#fff',
              border: '1px solid #ddd',
              borderRadius: '8px',
              padding: '16px 20px',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'flex-start'
            }}
          >
            <div>
              <p style={{ margin: 0, fontWeight: '600', color: '#222', fontSize: '15px' }}>{dept.name}</p>
              <p style={{ margin: '4px 0 0', fontSize: '13px', color: '#888' }}>{dept.description}</p>
              <p style={{ margin: '4px 0 0', fontSize: '13px', color: '#555' }}>
                Trưởng phòng: <strong>{dept.manager}</strong>
              </p>
            </div>
            <div style={{
              backgroundColor: '#e8f0fe',
              color: '#2563eb',
              borderRadius: '20px',
              padding: '4px 14px',
              fontSize: '13px',
              fontWeight: '600',
              whiteSpace: 'nowrap'
            }}>
              {dept.count} người
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Departments;
